from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png').convert('RGB')).astype(float)
g=.299*im[:,:,0]+.587*im[:,:,1]+.114*im[:,:,2]
gx=np.abs(np.diff(g,axis=1)); gy=np.abs(np.diff(g,axis=0))
print('vertical strong edges per y in x80:220 (>15):')
for y in range(35,141,5):
    xs=np.where(gx[y,80:220]>15)[0]+80
    # contiguous runs
    runs=[]
    for x in xs:
        if not runs or x>runs[-1][-1]+1:runs.append([int(x)])
        else:runs[-1].append(int(x))
    print(f'{y:3}', ' '.join(f'{r[0]}-{r[-1]}' for r in runs))
print('horizontal strong edges per x in y35:140 (>15):')
for x in range(80,221,10):
    ys=np.where(gy[35:140,x]>15)[0]+35
    runs=[]
    for y in ys:
        if not runs or y>runs[-1][-1]+1:runs.append([int(y)])
        else:runs[-1].append(int(y))
    print(f'{x:3}', ' '.join(f'{r[0]}-{r[-1]}' for r in runs))
PY"

